path, missing - added)) return true;\n        path.pop_back();\n    }\n    return false;\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m; \n    if(!(cin >> n >> m)) return 0;\n    adj.assign(n, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; cin >> u >> v; --u; --v;\n        adj[u] |= 1u << v;\n        adj[v] |= 1u << u;\n    }\n\n    int totalPairs = n * (n - 1) / 2;\n    int existing = 0;\n    for (int i = 0; i < n; ++i) existing += __builtin_popcount(adj[i]);\n    existing /= 2;\n    int missing = totalPairs - existing;\n\n    vector<int> bestPath;\n    for (int limit = 0; limit <= n; ++limit) {\n        vector<uint32_t> state = adj;\n        vector<int> path;\n        if (missing == 0) { bestPath = path; break; }\n        if (dfs(state, 0, limit, path, missing)) { bestPath = path; break; }\n    }\n\n    cout << bestPath.size() << \"\\n\";\n    for (size_t i = 0; i < bestPath.size(); ++i) {\n        cout << bestPath[i] << (i + 1 < bestPath.size() ? ' ' : '\\n');\n    }\n    if (bestPath.empty()) cout << \"\\n\";\n    return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe main.cpp -o party\n\n./party << 'EOF'\n5 6\n1 2\n1 3\n2 3\n2 5\n3 4\n4 5\nEOF\nEOF"
